class Solution:
    def minimumCost(self, nums: List[int]) -> int:
        n = len(nums)
        # dp[i][j] represents minimum cost to partition first i elements into j subarrays
        dp = [[float('inf')] * 4 for _ in range(n + 1)]
        dp[0][0] = 0

        for i in range(1, n + 1):
            for j in range(1, 4):  # j from 1 to 3
                for start in range(j - 1, i):  # start from j-1 because we need at least j-1 elements before to form j subarrays
                    if start == 0:
                        cost = nums[start]
                    else:
                        cost = nums[start] + dp[start][j - 1]
                    dp[i][j] = min(dp[i][j], cost)

        return dp[n][3]

class Solution:
    def maxFrequencyElements(self, nums: List[int]) -> int:
        freq = [0] * 101
        for num in nums:
            freq[num] += 1
        maxF = max(freq)
        ans = 0
        for f in freq:
            if f == maxF:
                ans += f
        return ans

class Solution:
    def areaOfMaxDiagonal(self, dimensions: List[List[int]]) -> int:
        max_diagonal_squared = 0
        max_area = 0

        for length, width in dimensions:
            diagonal_squared = length * length + width * width
            area = length * width

            if diagonal_squared > max_diagonal_squared:
                max_diagonal_squared = diagonal_squared
                max_area = area
            elif diagonal_squared == max_diagonal_squared:
                max_area = max(max_area, area)

        return max_area

class Solution:
    def missingInteger(self, nums: List[int]) -> int:
        num_set = set(nums)
        summ = nums[0]
        idx = 1
        while idx < len(nums) and nums[idx] == nums[idx - 1] + 1:
            summ += nums[idx]
            idx += 1
        while summ in num_set:
            summ += 1
        return summ

class Solution:
    def hasTrailingZeros(self, nums: List[int]) -> bool:
