class Solution:
    def incremovableSubarrayCount(self, nums: List[int]) -> int:
        n = len(nums)
        ans = 0

        # Generate all possible contiguous subarrays
        for i in range(n):
            for j in range(i, n):
                # Create remaining array after removing subarray [i, j]
                remaining = []
                # Add elements before subarray
                for k in range(i):
                    remaining.append(nums[k])
                # Add elements after subarray
                for k in range(j + 1, n):
                    remaining.append(nums[k])

                # Check if remaining array is strictly increasing
                valid = True
                for k in range(len(remaining) - 1):
                    if remaining[k] >= remaining[k + 1]:
                        valid = False
                        break

                if valid:
                    ans += 1

        return ans

class Solution:
    def findMissingAndRepeatedValues(self, grid: List[List[int]]) -> List[int]:
        n = len(grid)
        fre = [0] * (n * n + 1)
        for i in range(n):
            for j in range(n):
                fre[grid[i][j]] += 1
        rep = 0
        mis = 0
        for j in range(1, n * n + 1):
            if fre[j] == 0:
                mis = j
            elif fre[j] == 2:
                rep = j
        return [rep, mis]

