class Solution:
    def areSimilar(self, mat: List[List[int]], k: int) -> bool:
        original = [row[:] for row in mat]  # make a copy

        m = len(mat)
        for i in range(m):
            n = len(mat[i])
            if i % 2 == 0:  # even indexed row - left shift
                shift = k % n
                if shift > 0:
                    mat[i] = mat[i][shift:] + mat[i][:shift]
            else:  # odd indexed row - right shift
                shift = k % n
                if shift > 0:
                    mat[i] = mat[i][-shift:] + mat[i][:-shift]

        return mat == original

