class Solution:
    def findMinimumOperations(self, s1: str, s2: str, s3: str) -> int:
        if len(s1) == 0 or len(s2) == 0 or len(s3) == 0:
            return -1

        if s1[0] != s2[0] or s2[0] != s3[0] or s1[0] != s3[0]:
            return -1

        common_len = 0
        min_len = min(len(s1), len(s2), len(s3))

        for i in range(min_len):
            if s1[i] == s2[i] == s3[i]:
                common_len += 1
            else:
                break

        if common_len == 0:
            return -1

        return len(s1) + len(s2) + len(s3) - 3 * common_len

class Solution:
    def maximumStrongPairXor(self, nums: List[int]) -> int:
        max_xor = 0
        n = len(nums)
        for i in range(n):
            for j in range(n):
                x, y = nums[i], nums[j]
                if abs(x - y) <= min(x, y):
                    current_xor = x ^ y
                    max_xor = max(max_xor, current_xor)
        return max_xor

