                    break
            if isChampion:
                return i
        return -1

class Solution:
    def findKOr(self, nums: List[int], k: int) -> int:
        res = 0
        for i in range(32):
            n = 1 << i
            count = 0
            for num in nums:
                if num & n:
                    count += 1
            if count >= k:
                res |= n
        return res

