class Solution:
    def minimumSum(self, nums: List[int]) -> int:
        ans = float('inf')
        n = len(nums)
        for i in range(n):
            for j in range(i + 1, n):
                for k in range(j + 1, n):
                    if nums[i] < nums[j] and nums[k] < nums[j]:
                        current_sum = nums[i] + nums[j] + nums[k]
                        ans = min(ans, current_sum)
        return ans if ans != float('inf') else -1

class Solution:
    def findIndices(self, nums: List[int], indexDifference: int, valueDifference: int) -> List[int]:
        n = len(nums)
        for i in range(n):
            for j in range(n):
                if abs(i - j) >= indexDifference and abs(nums[i] - nums[j]) >= valueDifference:
                    return [i, j]
        return [-1, -1]

class Solution:
    def lastVisitedIntegers(self, words: List[str]) -> List[int]:
        collected = []
        result = []
        consecutive_prev = 0

        for word in words:
            if word == "prev":
                consecutive_prev += 1
                if consecutive_prev > len(collected):
                    result.append(-1)
                else:
                    # We need the (consecutive_prev - 1)th element from the end of collected
                    # which is the same as the (len(collected) - consecutive_prev)th element from the start
                    result.append(collected[-consecutive_prev])
            else:
                collected.append(int(word))
                consecutive_prev = 0

        return result

class Solution:
    def maximumTripletValue(self, nums: List[int]) -> int:
        max_arr = [-1] * len(nums)
        max_arr[-1] = nums[-1]
        for i in range(len(nums) - 2, -1, -1):
            max_arr[i] = max(max_arr[i + 1], nums[i])
        max_v = nums[0]
        res = 0
        for j in range(1, len(nums) - 1):
            tmp = (max_v - nums[j]) * max_arr[j + 1]
            res = max(res, tmp)
            max_v = max(max_v, nums[j])
        return res

class Solution:
    def minOperations(self, nums: List[int], k: int) -> int:
        collected = set()
        operations = 0

        # Iterate from the end of the array to the beginning
        for i in range(len(nums) - 1, -1, -1):
            operations += 1
            if nums[i] <= k:
                collected.add(nums[i])
                if len(collected) == k:
                    return operations

        return operations

class Solution:
    def maximumOddBinaryNumber(self, s: str) -> str:
        count_ones = s.count('1')
        res = []
        # Place (count_ones - 1) ones at the beginning
        for _ in range(count_ones - 1):
            res.append('1')
        # Fill remaining positions with zeros
        for _ in range(len(s) - count_ones):
            res.append('0')
        # Place the last one at the end to ensure the number is odd
        res.append('1')
        return ''.join(res)

