class Solution:
    def minimumRightShifts(self, nums: List[int]) -> int:
        n = len(nums)
        # Check if already sorted
        if all(nums[i] <= nums[i+1] for i in range(n-1)):
            return 0

        # Count breakpoints and find their positions
        breakpoints = []
        for i in range(n):
            if nums[i] > nums[(i+1) % n]:
                breakpoints.append(i)

        # More than one breakpoint means impossible to sort
        if len(breakpoints) > 1:
            return -1

        # Exactly one breakpoint: calculate shifts needed
        if len(breakpoints) == 1:
            return n - 1 - breakpoints[0]

        return -1

