class Solution:
    def maxSum(self, nums: List[int]) -> int:
        def max_digit(n):
            return max(int(d) for d in str(n))

        groups = {}
        for num in nums:
            digit = max_digit(num)
            if digit not in groups:
                groups[digit] = []
            groups[digit].append(num)

        max_sum = -1
        for digit, group in groups.items():
            if len(group) < 2:
                continue
            group.sort(reverse=True)
            max_sum = max(max_sum, group[0] + group[1])

        return max_sum

