class Solution:
    def alternatingSubarray(self, nums: List[int]) -> int:
        ans = -1
        n = len(nums)
        for i in range(n):
            for j in range(i + 1, n):
                if j - i == 1:
                    if nums[j] - nums[i] == 1:
                        ans = max(ans, 2)
                    else:
                        break
                else:
                    diff = nums[j] - nums[j-1]
                    expected_diff = 1 if (j - i) % 2 == 1 else -1
                    if diff != expected_diff:
                        break
                    ans = max(ans, j - i + 1)
        return ans

class Solution:
    def countOfPairs(self, n: int, x: int, y: int) -> List[int]:
        result = [0] * n

        for i in range(1, n + 1):
            for j in range(1, n + 1):
                if i != j:
                    direct_distance = abs(i - j)
                    min_distance = direct_distance

                    # Only consider shortcut if x != y
                    if x != y:
                        shortcut_distance = min(abs(i - x) + 1 + abs(y - j), abs(i - y) + 1 + abs(x - j))
                        min_distance = min(min_distance, shortcut_distance)

                    result[min_distance - 1] += 1

        return result

class Solution:
    def minimumPushes(self, word: str) -> int:
        from collections import Counter
        freq = Counter(word)
        sorted_freqs = sorted(freq.values(), reverse=True)
        result = 0
        for i, count in enumerate(sorted_freqs):
            push_cost = (i // 8) + 1
            result += count * push_cost
        return result

class Solution:
    def canSortArray(self, nums: List[int]) -> bool:
        from collections import defaultdict

        # Group indices by their bit count
        groups = defaultdict(list)
        for i, num in enumerate(nums):
            bit_count = bin(num).count('1')
            groups[bit_count].append(i)

        # Sort each group by the actual value at those indices
        for bit_count in groups:
            indices_in_group = groups[bit_count]
            # Get the values at these indices and sort them
            sorted_values = sorted([nums[i] for i in indices_in_group])
            # Reassign sorted values back to the original indices within this group
            for j, idx in enumerate(indices_in_group):
                nums[idx] = sorted_values[j]

        # Check if the array is sorted
        for i in range(1, len(nums)):
            if nums[i] < nums[i-1]:
                return False

        return True

