class Solution:
    def minOperations(self, nums: List[int], k: int) -> int:
        total_xor = 0
        for num in nums:
            total_xor ^= num
        count = 0
        xor_diff = total_xor ^ k
        while xor_diff:
            count += xor_diff & 1
            xor_diff >>= 1
        return count

from collections import deque

class Solution:
    def minimumOperationsToMakeEqual(self, x: int, y: int) -> int:
        if x == y:
            return 0

        queue = deque([(x, 0)])
        visited = set([x])

        while queue:
            curr, steps = queue.popleft()

            # Try all possible operations
            next_states = []

            # Increment by 1
            next_states.append(curr + 1)
            # Decrement by 1
            next_states.append(curr - 1)
            # Divide by 11 if divisible
            if curr % 11 == 0:
                next_states.append(curr // 11)
            # Divide by 5 if divisible
            if curr % 5 == 0:
                next_states.append(curr // 5)

            for next_state in next_states:
                if next_state == y:
                    return steps + 1
                if next_state not in visited and 1 <= next_state <= 10000:
                    visited.add(next_state)
                    queue.append((next_state, steps + 1))

        return -1  # Should never reach here given constraints

class Solution:
    def maximumLength(self, s: str) -> int:
        n = len(s)
        max_len = -1

        # Try all possible lengths from largest to smallest
        for length in range(n, 0, -1):
            # Count occurrences of each special substring of current length
            seen = {}
            for i in range(n - length + 1):
                substr = s[i:i + length]
                # Check if it's special (all same characters)
                if len(set(substr)) == 1:
                    seen[substr] = seen.get(substr, 0) + 1
                    if seen[substr] >= 3:
                        return length

        return -1

class Solution:
    def maximizeSquareArea(self, m: int, n: int, hFences: List[int], vFences: List[int]) -> int:
        mod = 10**9 + 7
        hFences.extend([1, m])
        vFences.extend([1, n])
        hFences.sort()
        vFences.sort()

        horizontal_diffs = set()
        for i in range(len(hFences)):
            for j in range(i + 1, len(hFences)):
                horizontal_diffs.add(hFences[j] - hFences[i])

        max_side = -1
        for i in range(len(vFences)):
            for j in range(i + 1, len(vFences)):
                vertical_diff = vFences[j] - vFences[i]
                if vertical_diff in horizontal_diffs:
                    max_side = max(max_side, vertical_diff)

        return max_side * max_side % mod if max_side != -1 else -1

class Solution:
    def largestPerimeter(self, nums: List[int]) -> int:
        nums.sort()
        total = sum(nums)
        for i in range(len(nums) - 1, 1, -1):
            if total - nums[i] > nums[i]:
                return total
            total -= nums[i]
        return -1

class Solution:
    def divideArray(self, nums: List[int], k: int) -> List[List[int]]:
        nums.sort()
        result = []
        for i in range(0, len(nums), 3):
            triplet = nums[i:i+3]
            if triplet[-1] - triplet[0] > k:
                return []
            result.append(triplet)
        return result

class Solution:
    def minimumCost(self, nums: List[int]) -> int:
        def pal(x):
            s = str(x)
            return s == s[::-1]

        nums.sort()
        median = nums[len(nums) // 2]
        left = right = median

        while not pal(left):
            left -= 1
        while not pal(right):
            right += 1

        cost_left = sum(abs(x - left) for x in nums)
        cost_right = sum(abs(x - right) for x in nums)

        return min(cost_left, cost_right)

