    def getGoodIndices(self, variables: List[List[int]], target: int) -> List[int]:
        ans = []
        for i in range(len(variables)):
            a, b, c, m = variables[i]
            result = pow(pow(a, b, 10), c, m)
            if result == target:
                ans.append(i)
        return ans

class Solution:
    def countSubarrays(self, nums: List[int], k: int) -> int:
        max_val = max(nums)
        left = 0
        count = 0
        result = 0

        for right in range(len(nums)):
            if nums[right] == max_val:
                count += 1

            while count >= k:
                if nums[left] == max_val:
                    count -= 1
                left += 1

            result += left

        return result

class Solution:
    def removeAlmostEqualCharacters(self, word: str) -> int:
        def is_almost_equal(a, b):
            return a == b or abs(ord(a) - ord(b)) == 1

        ans = 0
        ind = 1

        while ind < len(word):
            if is_almost_equal(word[ind], word[ind-1]):
                ans += 1
                ind += 2
            else:
                ind += 1

        return ans

class Solution:
    def maxSubarrayLength(self, nums: List[int], k: int) -> int:
        left = 0
        result = 0
        freq = {}

        for right in range(len(nums)):
            num = nums[right]
            freq[num] = freq.get(num, 0) + 1

            while freq[num] > k:
                freq[nums[left]] -= 1
                left += 1

            result = max(result, right - left + 1)

        return result

class Solution:
    def minimumAddedCoins(self, coins: List[int], target: int) -> int:
        coins.sort()
        max_sofar = 0
        ans = 0
        i = 0

        while max_sofar < target:
            if i < len(coins) and coins[i] <= max_sofar + 1:
                max_sofar += coins[i]
                i += 1
            else:
                # Add coin of value max_sofar + 1
                ans += 1
                max_sofar += max_sofar + 1

        return ans

class Solution:
    def beautifulSubstrings(self, s: str, k: int) -> int:
        vowels = set('aeiou')
        count = 0
        n = len(s)

        for i in range(n):
            vowel_count = 0
            consonant_count = 0

            for j in range(i, n):
                if s[j] in vowels:
                    vowel_count += 1
                else:
                    consonant_count += 1

                if vowel_count == consonant_count and (vowel_count * consonant_count) % k == 0:
                    count += 1

        return count

class Solution:
    def maximizeSquareHoleArea(self, n: int, m: int, hBars: List[int], vBars: List[int]) -> int:
        hBars.sort()
        vBars.sort()

        hmax = 1
        vmax = 1

        for i in range(1, len(hBars)):
            if hBars[i] == hBars[i-1] + 1:
                hmax += 1
            else:
                hmax = 1

        for i in range(1, len(vBars)):
            if vBars[i] == vBars[i-1] + 1:
                vmax += 1
            else:
                vmax = 1

        side = min(hmax + 1, vmax + 1)
        return side * side

class Solution:
    def minimumSteps(self, s: str) -> int:
        cnt = 0
