class Solution:
    def maximumXorProduct(self, a: int, b: int, n: int) -> int:
        MOD = 10**9 + 7
        x = 0
        for i in range(n-1, -1, -1):
            bit_mask = 1 << i
            x0 = x
            x1 = x | bit_mask

            val0 = (a ^ x0) * (b ^ x0)
            val1 = (a ^ x1) * (b ^ x1)

            if val1 > val0:
                x = x1
        return (a ^ x) * (b ^ x) % MOD

class Solution:
    def minOperations(self, nums1: List[int], nums2: List[int]) -> int:
        n = len(nums1)

        # Try both scenarios: swap last pair or don't swap last pair
        def solve_with_last_swap(last_swapped):
            # Create copies
            a = nums1[:]
            b = nums2[:]

            if last_swapped:
                a[n-1], b[n-1] = b[n-1], a[n-1]

            swaps = 0

            # Process all positions except the last one
            for i in range(n - 1):
                # Check if current state satisfies conditions
                if a[i] > a[n-1] or b[i] > b[n-1]:
                    # Try swapping
                    if a[i] <= b[n-1] and b[i] <= a[n-1]:
                        swaps += 1
                        a[i], b[i] = b[i], a[i]
                    else:
                        return float('inf')  # Impossible to satisfy
                # If current state is already good, continue

            # Final check: ensure last elements are maximums
            if last_swapped:
                if a[n-1] < max(a[:n-1]) or b[n-1] < max(b[:n-1]):
                    return float('inf')
            else:
                if a[n-1] < max(a[:n-1]) or b[n-1] < max(b[:n-1]):
                    return float('inf')

            return swaps

        result1 = solve_with_last_swap(False)
        result2 = solve_with_last_swap(True)

        if result1 == float('inf') and result2 == float('inf'):
            return -1
        else:
            return min(result1, result2)

class Solution:
    def distributeCandies(self, n: int, limit: int) -> int:
        result = 0
        for k in range(min(n, limit) + 1):
            m = n - k
            if m > 2 * limit:
                continue
            ways = max(0, min(m, limit) - max(m - limit, 0)) + 1
            result += ways
        return result

class Solution:
    def findChampion(self, n: int, edges: List[List[int]]) -> int:
        incoming = [0] * n
        for u, v in edges:
            incoming[v] += 1
        champion_count = 0
        champion = -1
        for i in range(n):
            if incoming[i] == 0:
                champion_count += 1
                champion = i
        return champion if champion_count == 1 else -1

class Solution:
    def minSum(self, nums1: List[int], nums2: List[int]) -> int:
        sum1 = sum(nums1)
        cnt1 = nums1.count(0)
        sum2 = sum(nums2)
        cnt2 = nums2.count(0)

        if cnt1 == 0 and cnt2 == 0:
            return sum1 if sum1 == sum2 else -1
        elif cnt1 == 0:
            return sum1 if sum1 >= sum2 + cnt2 else -1
        elif cnt2 == 0:
            return sum2 if sum2 >= sum1 + cnt1 else -1
        else:
            return max(sum1 + cnt1, sum2 + cnt2)

class Solution:
    def minIncrementOperations(self, nums: List[int], k: int) -> int:
        total_operations = 0
        n = len(nums)

        for i in range(2, n):
            triplet = [nums[i-2], nums[i-1], nums[i]]
            current_max = max(triplet)

            if current_max < k:
                best_val = max(triplet)
                idx_in_triplet = -1
                for j in range(3):
                    if triplet[j] == best_val:
                        idx_in_triplet = j
                        break

                if idx_in_triplet == 0:
                    nums[i-2] += k - best_val
                elif idx_in_triplet == 1:
                    nums[i-1] += k - best_val
                else:
                    nums[i] += k - best_val

                total_operations += k - best_val

        return total_operations

