class Solution:
    def lengthOfLongestSubsequence(self, nums: List[int], target: int) -> int:
        f = [-float('inf')] * (target + 1)
        f[0] = 0

        for x in nums:
            for c in range(target, x - 1, -1):
                if f[c - x] != -float('inf'):
                    f[c] = max(f[c], f[c - x] + 1)

        return f[target] if f[target] != -float('inf') else -1

class Solution:
    def minimumSum(self, nums: List[int]) -> int:
        n = len(nums)
        min_sum = float('inf')
        found = False

        for j in range(1, n - 1):
            for i in range(j):
                for k in range(j + 1, n):
                    if nums[i] < nums[j] and nums[k] < nums[j]:
                        current_sum = nums[i] + nums[j] + nums[k]
                        min_sum = min(min_sum, current_sum)
                        found = True

        return min_sum if found else -1

class Solution:
    def constructProductMatrix(self, grid: List[List[int]]) -> List[List[int]]:
        MOD = 12345
        n, m = len(grid), len(grid[0])
        result = [[0] * m for _ in range(n)]

        # For each cell, calculate product of all other cells
        for i in range(n):
            for j in range(m):
                product = 1
                for x in range(n):
                    for y in range(m):
                        if x == i and y == j:
                            continue
                        product = (product * grid[x][y]) % MOD
                result[i][j] = product

        return result

