class Solution:
    def minSizeSubarray(self, nums: List[int], target: int) -> int:
        total = sum(nums)
        n = len(nums)

        # If target is 0, return 0 (empty subarray)
        if target == 0:
            return 0

        # Calculate how many full copies we need
        full_copies = target // total
        remaining = target % total

        # If remaining is 0, we need full_copies copies
        if remaining == 0:
            # Find shortest subarray with sum = total
            prefix = [0]
            for num in nums:
                prefix.append(prefix[-1] + num)

            min_len = float('inf')
            # Check all possible subarrays
            for i in range(n):
                for j in range(i + 1, n + 1):
                    if prefix[j] - prefix[i] == total:
                        min_len = min(min_len, j - i)

            if min_len == float('inf'):
                return -1
            else:
                return min_len * full_copies

        # For remaining part, find shortest subarray with sum = remaining
        # Use sliding window approach
        # We'll extend the array to handle wraparound
        extended_nums = nums + nums
        n_extended = len(extended_nums)

        # Use dictionary to store first occurrence of prefix sum
        prefix_sum_dict = {0: -1}  # dummy value for index 0

        current_sum = 0
        min_length = float('inf')

        for i in range(n_extended):
            current_sum += extended_nums[i]

            # Look for prefix_sum - remaining
            needed_sum = current_sum - remaining
            if needed_sum in prefix_sum_dict:
                min_length = min(min_length, i - prefix_sum_dict[needed_sum])

            # Store current prefix sum if not seen before
            if current_sum not in prefix_sum_dict:
                prefix_sum_dict[current_sum] = i

        if min_length == float('inf'):
            return -1
        else:
            return min_length + full_copies * n

from collections import Counter

class Solution:
    def minOperations(self, nums: List[int]) -> int:
        freq = Counter(nums)
        total_ops = 0

        for count in freq.values():
            if count == 1:
                return -1

            # Greedy: use as many groups of 3 as possible
            if count % 3 == 0:
                total_ops += count // 3
            elif count % 3 == 1:
                # Replace one group of 3 with two groups of 2 (since 3 + 1 = 2 + 2)
                total_ops += count // 3 - 1 + 2
            else:  # count % 3 == 2
                total_ops += count // 3 + 1

        return total_ops

class Solution:
    def maxSubarrays(self, nums: List[int]) -> int:
        total_and = nums[0]
        for num in nums[1:]:
            total_and &= num

        count = 0
        current_and = nums[0]

        for i in range(len(nums)):
            current_and &= nums[i]
            if current_and == total_and:
                count += 1
                if i < len(nums) - 1:
                    current_and = nums[i + 1]
                else:
                    break

        return count

class Solution:
    def maximumSumOfHeights(self, maxHeights: List[int]) -> int:
        n = len(maxHeights)
        maxSum = float('-inf')

        for peak in range(n):
            mountain = [float('inf')] * n
            mountain[peak] = maxHeights[peak]

            # Traverse left from peak
            for i in range(peak - 1, -1, -1):
                mountain[i] = min(maxHeights[i], mountain[i + 1])

            # Traverse right from peak
            for j in range(peak + 1, n):
                mountain[j] = min(maxHeights[j], mountain[j - 1])

            currentSum = sum(mountain)
            maxSum = max(maxSum, currentSum)

        return maxSum

class Solution:
    def minLengthAfterRemovals(self, nums: List[int]) -> int:
        left, right = 0, len(nums) - 1
        while left < right:
            if nums[left] < nums[right]:
                left += 1
                right -= 1
            else:
                left += 1
        return right - left + 1

class Solution:
    def countPairs(self, coordinates: List[List[int]], k: int) -> int:
        from collections import defaultdict
        freq = defaultdict(int)
        result = 0

        for x, y in coordinates:
            for dx in range(k + 1):
                dy = k - dx
                a = x ^ dx
                b = y ^ dy
                result += freq[(a, b)]
            freq[(x, y)] += 1

        return result

class Solution:
