        min_time = max(dx, dy)

        if sx == fx and sy == fy:
            return t != 1

        return t >= min_time

class Solution:
    def minimumOperations(self, num: str) -> int:
        n = len(num)
        ans = float('inf')

        # Check for single '0'
        if '0' in num:
            # We can keep any '0' and delete everything else
            # But if the string is "0", we need 0 deletions
            # Otherwise, we need n-1 deletions
            if n == 1:
                ans = 0
            else:
                ans = min(ans, n - 1)

        # Check for valid endings
        for i in range(n):
            for j in range(i + 1, n):
                # Check if the two-digit number formed by num[i] and num[j] is divisible by 25
                if num[i] + num[j] in ['00', '25', '50', '75']:
                    # We keep digits from position 0 to i-1, then keep digits at positions i and j
                    # Total kept digits: i + 2
                    # Deletions: n - (i + 2)
                    deletions = n - i - 2
                    ans = min(ans, deletions)

        return ans

class Solution:
    def maxSum(self, nums: List[int], m: int, k: int) -> int:
        maxSum = 0
        currentSum = 0
        elementFrequency = {}
        left = 0

        for right in range(len(nums)):
            currentElement = nums[right]
            elementFrequency[currentElement] = elementFrequency.get(currentElement, 0) + 1
            currentSum += currentElement

            while right - left + 1 > k:
                leftElement = nums[left]
                elementFrequency[leftElement] -= 1
                if elementFrequency[leftElement] == 0:
                    del elementFrequency[leftElement]
                currentSum -= leftElement
                left += 1

            if len(elementFrequency) >= m:
                maxSum = max(maxSum, currentSum)

        return maxSum

class Solution:
    def minimumPossibleSum(self, n: int, target: int) -> int:
        k = target // 2
        if n <= k:
            return n * (n + 1) // 2
        sum1 = k * (k + 1) // 2
        sum2 = (target + target + n - k - 1) * (n - k) // 2
        return sum1 + sum2

class Solution:
    def minimumSum(self, n: int, k: int) -> int:
        chosen = set()
        total_sum = 0
        current = 1

        while len(chosen) < n:
            complement = k - current
            if complement not in chosen:
                chosen.add(current)
                total_sum += current
            current += 1

        return total_sum

class Solution:
    def maximizeTheProfit(self, n: int, offers: List[List[int]]) -> int:
        # Sort offers by end position
        offers.sort(key=lambda x: x[1])

        # dp[i] represents the maximum gold achievable up to house i (inclusive)
        dp = [0] * n

        for start, end, gold in offers:
            # Calculate the maximum profit achievable before this offer starts
            prev_max = dp[start - 1] if start > 0 else 0

            # Update dp[end] with the maximum of either taking this offer or not taking it
            dp[end] = max(dp[end], prev_max + gold)

        return max(dp)

class Solution:
