        for a in range(n + 1):
            for b in range(a, n + 1):
                ops = 0
                for i in range(n):
                    num = i
                    desired_group = 1 if i < a else (2 if i < b else 3)
                    if nums[i] != desired_group:
                        ops += 1
                min_ops = min(min_ops, ops)

        return min_ops

import bisect
from typing import List

class Solution:
    def minAbsoluteDifference(self, nums: List[int], x: int) -> int:
        if x == 0:
            return 0

        result = float('inf')
        # Maintain a sorted list of elements from indices [0, i-x]
        S = []

        for i in range(len(nums)):
            # Add nums[i-x] to S if i >= x
            if i >= x:
                bisect.insort(S, nums[i - x])

            # Find position where nums[i] would be inserted
            pos = bisect.bisect_left(S, nums[i])

            # Check element at position pos (if exists)
            if pos < len(S):
                result = min(result, abs(nums[i] - S[pos]))

            # Check element just before position pos (if exists)
            if pos > 0:
                result = min(result, abs(nums[i] - S[pos - 1]))

        return result

class Solution:
    def canSplitArray(self, nums: List[int], m: int) -> bool:
        from functools import lru_cache

        @lru_cache(None)
        def dfs(left, right):
            if left == right:
                return True
            if right - left + 1 <= 2:
                return True

            total = sum(nums[left:right+1])
            for i in range(left, right):
                left_sum = sum(nums[left:i+1])
                right_sum = total - left_sum
                if (left_sum >= m or i + 1 - left == 1) and (right_sum >= m or right - i == 1):
                    if dfs(left, i) and dfs(i+1, right):
                        return True
            return False

        return dfs(0, len(nums)-1)

class Solution:
    def minimumSeconds(self, nums: List[int]) -> int:
        n = len(nums)
        counter = {}

        for i in range(n):
            if nums[i] not in counter:
                counter[nums[i]] = []
            counter[nums[i]].append(i)

        ans = float('inf')

        for value, positions in counter.items():
            max_gap = 0
            positions.sort()

            # Calculate maximum gap between consecutive positions (circular)
            for j in range(len(positions)):
                gap = positions[(j + 1) % len(positions)] - positions[j]
                if j == len(positions) - 1:
                    gap = positions[0] + n - positions[j]
                max_gap = max(max_gap, gap)

            # Minimum seconds needed for this value is half the maximum gap
            ans = min(ans, max_gap // 2)

        return ans

class Solution:
    def countCompleteSubarrays(self, nums: List[int]) -> int:
        m = len(set(nums))
