class Solution:
    def maxArrayValue(self, nums: List[int]) -> int:
        res = max(nums)
        arr = nums[:]

        while True:
            merged = False
            for i in range(len(arr) - 1):
                if arr[i] <= arr[i + 1]:
                    arr[i + 1] += arr[i]
                    res = max(res, arr[i + 1])
                    arr.pop(i)
                    merged = True
                    break

            if not merged:
                break

        return res

class Solution:
    def sortVowels(self, s: str) -> str:
        vowels = set('aeiouAEIOU')
        vowel_list = [char for char in s if char in vowels]
        vowel_list.sort()

        result = []
        vowel_index = 0

        for char in s:
            if char in vowels:
                result.append(vowel_list[vowel_index])
                vowel_index += 1
            else:
                result.append(char)

        return ''.join(result)

class Solution:
    def maxScore(self, nums: List[int], x: int) -> int:
        n = len(nums)
        # dp[i][parity] represents max score ending at i with last visited number having given parity
        # parity 0 for even, 1 for odd
        dp = [[-float('inf')] * 2 for _ in range(n)]

        # Start at position 0
        dp[0][nums[0] % 2] = nums[0]

        for i in range(1, n):
            for j in range(i):
                # Try to move from j to i
                penalty = x if (nums[j] % 2 != nums[i] % 2) else 0
                current_score = dp[j][nums[j] % 2] + nums[i] - penalty
                dp[i][nums[i] % 2] = max(dp[i][nums[i] % 2], current_score)

        # Return maximum score among all positions
        return max(max(row) for row in dp)

class Solution:
    def numberOfWays(self, n: int, x: int) -> int:
        MOD = 10**9 + 7
        dp = [0] * (n + 1)
        dp[0] = 1

        powers = []
        for i in range(1, n + 1):
            powers.append(i ** x)

        for power in powers:
            dpn = dp[:]
            for j in range(n + 1):
                if j >= power:
                    dpn[j] = (dpn[j] + dp[j - power]) % MOD
            dp = dpn

        return dp[n]

class Solution:
    def maximumBeauty(self, nums: List[int], k: int) -> int:
        events = []
        for num in nums:
            events.append((num - k, 1))      # start event
            events.append((num + k, -1))     # end event

        events.sort()
        max_beauty = 0
        current = 0
        for time, delta in events:
            current += delta
            max_beauty = max(max_beauty, current)

        return max_beauty

class Solution:
    def minimumIndex(self, nums: List[int]) -> int:
        n = len(nums)
        # Find the dominant element in the entire array
        freq = {}
        for num in nums:
            freq[num] = freq.get(num, 0) + 1

        dominant = None
        for num, count in freq.items():
            if count * 2 > n:
                dominant = num
                break

        # Iterate through each possible split index
        left_count = 0
        for i in range(n - 1):  # i from 0 to n-2
            if nums[i] == dominant:
                left_count += 1

            left_len = i + 1
            right_len = n - i - 1  # Corrected: right subarray length is n - i - 1
            right_count = freq[dominant] - left_count

            # Check if both subarrays have the dominant element as their dominant
            if left_count * 2 > left_len and right_count * 2 > right_len:
                return i

        return -1

class Solution:
    def maximumJumps(self, nums: List[int], target: int) -> int:
        n = len(nums)
        dp = [-1] * n
        dp[0] = 0

        for i in range(n - 1):
            if dp[i] == -1:
                continue
            for j in range(i + 1, n):
                if abs(nums[j] - nums[i]) <= target:
                    dp[j] = max(dp[j], dp[i] + 1)

        return dp[n - 1]

class Solution:
    def maxNonDecreasingLength(self, nums1: List[int], nums2: List[int]) -> int:
        prev_elems = (0, 0)
        prev_lengths = [0, 0]
        result = 0

        for a, b in zip(nums1, nums2):
            current_lengths = [1, 1]

            # Check if a can extend subarray ending with prev_elems[0]
            if a >= prev_elems[0]:
                current_lengths[0] = max(current_lengths[0], prev_lengths[0] + 1)
            # Check if a can extend subarray ending with prev_elems[1]
            if a >= prev_elems[1]:
                current_lengths[0] = max(current_lengths[0], prev_lengths[1] + 1)

            # Check if b can extend subarray ending with prev_elems[0]
            if b >= prev_elems[0]:
                current_lengths[1] = max(current_lengths[1], prev_lengths[0] + 1)
            # Check if b can extend subarray ending with prev_elems[1]
            if b >= prev_elems[1]:
                current_lengths[1] = max(current_lengths[1], prev_lengths[1] + 1)

            result = max(result, max(current_lengths))
            prev_elems = (a, b)
            prev_lengths = current_lengths[:]

        return result

class Solution:
    def checkArray(self, nums: List[int], k: int) -> bool:
        operations = 0  # Number of operations applied so far

        for i in range(len(nums)):
            # Subtract the effect of previously applied operations
            nums[i] -= operations

            # If current element becomes negative, impossible
            if nums[i] < 0:
                return False

            # If we're at the start of a new subarray (i % k == 0),
            # then the current value represents how many operations
            # should be applied from this position onwards
            if i % k == 0:
                operations = nums[i]
            else:
                # We don't need to do anything special here
                pass

        return True

class Solution:
    def relocateMarbles(self, nums: List[int], moveFrom: List[int], moveTo: List[int]) -> List[int]:
        occupied = set(nums)
        for i in range(len(moveFrom)):
            from_pos = moveFrom[i]
            to_pos = moveTo[i]
            if from_pos in occupied:
                occupied.remove(from_pos)
                occupied.add(to_pos)
        return sorted(list(occupied))

class Solution:
    def minimumBeautifulSubstrings(self, s: str) -> int:
        n = len(s)
        # Precompute all powers of 5 up to maximum possible value (2^n - 1)
        max_val = (1 << n) - 1
        powers_of_5 = set()
        power = 1
        while power <= max_val:
            powers_of_5.add(power)
            power *= 5

        # dp[i] = minimum number of beautiful substrings needed for s[0:i]
        dp = [float('inf')] * (n + 1)
        dp[0] = 0

        for i in range(1, n + 1):
            for j in range(i):
                # Check leading zero
                if s[j] == '0':
                    continue

                # Convert substring s[j:i] to decimal
                num = 0
                for k in range(j, i):
                    num = num * 2 + int(s[k])

                # Check if it's a power of 5
                if num in powers_of_5:
                    dp[i] = min(dp[i], dp[j] + 1)

        return dp[n] if dp[n] != float('inf') else -1

class Solution:
    def findPrimePairs(self, n: int) -> List[List[int]]:
        ans = []
        prime = [True] * (n + 1)
        prime[0] = prime[1] = False

        for i in range(2, int(n**0.5) + 1):
            if prime[i]:
                for j in range(i*i, n + 1, i):
                    prime[j] = False

        for x in range(2, n // 2 + 1):
            y = n - x
            if x <= y and prime[x] and prime[y]:
                ans.append([x, y])

        return ans

class Solution:
    def continuousSubarrays(self, nums: List[int]) -> int:
        left = 0
        result = 0

        for right in range(len(nums)):
            # Shrink window from left until condition is satisfied
            while left <= right:
                min_val = min(nums[left:right+1])
                max_val = max(nums[left:right+1])

                if max_val - min_val <= 2:
                    break
                left += 1

            # Add count of valid subarrays ending at 'right'
            result += right - left + 1

        return result

class Solution:
    def numberOfPowerfulInt(self, start: int, finish: int, limit: int, s: str) -> int:
        def count_up_to(n):
            if n < 0:
                return 0
            n_str = str(n)
            len_n = len(n_str)
            len_s = len(s)

            # If s is longer than n, then even s itself is too long
            if len_s > len_n:
                return 0

            from functools import lru_cache

            @lru_cache(maxsize=None)
            def dp(pos, tight, suffix_idx, started):
                # Base case: we've placed all digits
                if pos == len_n:
                    # We must have matched all digits of s
                    return 1 if suffix_idx == len_s else 0

                res = 0
                max_digit = int(n_str[pos]) if tight else limit

                # Determine if we're in the suffix region
                suffix_start = len_n - len_s
                in_suffix_region = pos >= suffix_start

                if in_suffix_region:
                    # Must place the next digit of s
                    if suffix_idx >= len_s:
                        return 0  # Safety check

                    required_digit = int(s[suffix_idx])

                    # Check if required_digit is within limit
                    if required_digit > limit:
                        return 0

                    # Check tight constraint
                    if tight and required_digit > max_digit:
                        return 0

                    # Place the required digit
                    new_tight = tight and (required_digit == max_digit)
                    new_suffix_idx = suffix_idx + 1
                    new_started = started or (required_digit > 0)

                    res += dp(pos + 1, new_tight, new_suffix_idx, new_started)
                else:
                    # Not in suffix region: can place any digit from 0 to max_digit
                    for d in range(0, max_digit + 1):
                        if d > limit:
                            continue
                        new_tight = tight and (d == max_digit)
                        new_started = started or (d > 0)
                        new_suffix_idx = suffix_idx

                        res += dp(pos + 1, new_tight, new_suffix_idx, new_started)

                return res

            return dp(0, True, 0, False)

        return count_up_to(finish) - count_up_to(start - 1)

class Solution:
    def incremovableSubarrayCount(self, nums: List[int]) -> int:
        n = len(nums)
        count = 0

        # Precompute longest strictly increasing prefix ending at each index
        left_valid = [0] * n
        for i in range(n):
            if i == 0:
                left_valid[i] = 1
            else:
                if nums[i] > nums[i-1]:
                    left_valid[i] = left_valid[i-1] + 1
                else:
                    left_valid[i] = 1

        # Precompute longest strictly increasing suffix starting at each index
        right_valid = [0] * n
        for i in range(n-1, -1, -1):
            if i == n-1:
                right_valid[i] = 1
            else:
                if nums[i] < nums[i+1]:
                    right_valid[i] = right_valid[i+1] + 1
                else:
                    right_valid[i] = 1

        # For each possible removal window [left, right]
        for left in range(n):
            for right in range(left, n):
                # Check if removing [left, right] leaves strictly increasing array

                # Check left part [0, left-1] is strictly increasing
                left_ok = True
                if left > 0:
                    # Check if the entire left part is strictly increasing
                    # We can use our precomputed array
                    if left_valid[left-1] != left:
                        left_ok = False

                # Check right part [right+1, n-1] is strictly increasing
                right_ok = True
                if right < n-1:
                    # Check if the entire right part is strictly increasing
                    # We can use our precomputed array
                    if right_valid[right+1] != n - right - 1:
                        right_ok = False

                # Check connectivity between left and right parts
                if left_ok and right_ok:
                    if left == 0 and right == n-1:
                        count += 1
                    elif left == 0:
                        # Only right part exists
                        count += 1
                    elif right == n-1:
                        # Only left part exists
                        count += 1
                    else:
                        # Both parts exist
                        if left > 0 and right < n-1:
                            if nums[left-1] < nums[right+1]:
                                count += 1

        return count

class Solution:
    def maxFrequencyScore(self, nums: List[int], k: int) -> int:
        nums.sort()
        n = len(nums)

        def canAchieve(freq):
            if freq == 0:
                return True
            if freq > n:
                return False

            # Try all possible contiguous segments of length 'freq'
            for i in range(n - freq + 1):
                j = i + freq - 1
                # Calculate minimum operations to make all elements in [i,j] equal
                # Use median (middle element) as target value
                median_idx = i + freq // 2
                target = nums[median_idx]

                cost = 0
                for idx in range(i, j + 1):
                    cost += abs(nums[idx] - target)

                if cost <= k:
                    return True

            return False

        # Binary search on the answer
        left, right = 1, n
        result = 1

        while left <= right:
            mid = (left + right) // 2
            if canAchieve(mid):
                result = mid
                left = mid + 1
            else:
                right = mid - 1

        return result

class Solution:
    def numberOfGoodPartitions(self, nums: List[int]) -> int:
        first_occurrence = {}
        last_occurrence = {}

        for i, num in enumerate(nums):
            if num not in first_occurrence:
                first_occurrence[num] = i
            last_occurrence[num] = i

        intervals = []
        for num in first_occurrence:
            intervals.append([first_occurrence[num], last_occurrence[num]])

        intervals.sort(key=lambda x: x[0])

        merged = []
        for start, end in intervals:
            if not merged or merged[-1][1] < start:
                merged.append([start, end])
            else:
                merged[-1][1] = max(merged[-1][1], end)

        k = len(merged)
        MOD = 10**9 + 7
        return pow(2, k - 1, MOD)

class Solution:
    def numberOfSets(self, n: int, maxDistance: int, roads: List[List[int]]) -> int:
        ans = 0
        # Generate all possible subsets of branches using bit manipulation
        for mask in range(1 << n):
            # Initialize distance matrix with infinity
            g = [[float('inf')] * n for _ in range(n)]
            # Set diagonal to 0 (distance from a node to itself is 0)
            for i in range(n):
                g[i][i] = 0

            # Populate direct road weights if both endpoints are active in current subset
            for u, v, w in roads:
                if (mask >> u) & 1 and (mask >> v) & 1:
                    g[u][v] = min(g[u][v], w)
                    g[v][u] = min(g[v][u], w)

            # Apply Floyd-Warshall algorithm to compute shortest paths between all pairs
            for k in range(n):
                for i in range(n):
                    for j in range(n):
                        if g[i][k] + g[k][j] < g[i][j]:
                            g[i][j] = g[i][k] + g[k][j]

            # Check if maximum distance between any two active branches is <= maxDistance
            valid = True
            for i in range(n):
                if not ((mask >> i) & 1):  # Skip inactive branches
                    continue
                for j in range(n):
                    if not ((mask >> j) & 1):  # Skip inactive branches
                        continue
                    if i != j and g[i][j] > maxDistance:
                        valid = False
                        break
                if not valid:
                    break

            if valid:
                ans += 1

        return ans

class Solution:
    def countCompleteSubstrings(self, word: str, k: int) -> int:
        total = 0
        n = len(word)

        # Split string into segments where adjacent characters differ by more than 2
        segments = []
        start = 0
        for i in range(1, n):
            if abs(ord(word[i]) - ord(word[i-1])) > 2:
                segments.append(word[start:i])
                start = i

        segments.append(word[start:])

        for segment in segments:
            # Try all possible starting positions
            for left in range(len(segment)):
                freq = {}
                for right in range(left, len(segment)):
                    char = segment[right]
                    freq[char] = freq.get(char, 0) + 1

                    # Check if current window is valid
                    window_size = right - left + 1

                    # Only check validity if window size is divisible by k
                    if window_size % k == 0:
                        # Check if all characters appear exactly k times
                        valid = True
                        for count in freq.values():
                            if count != k:
                                valid = False
                                break

                        if valid:
                            total += 1

        return total

class Solution:
    def beautifulSubstrings(self, s: str, k: int) -> int:
        vowels = set('aeiou')
        count = 0
        n = len(s)

        for i in range(n):
            vowel_count = 0
            consonant_count = 0

            for j in range(i, n):
                if s[j] in vowels:
                    vowel_count += 1
                else:
                    consonant_count += 1

                # Check if substring s[i:j+1] is beautiful
                if vowel_count == consonant_count and (vowel_count * consonant_count) % k == 0:
                    count += 1

        return count

class Solution:
    def findMaximumLength(self, nums: List[int]) -> int:
        stack = []
        for num in nums:
            # Try to add num to stack
            while stack and stack[-1] > num:
                stack.pop()
            stack.append(num)
        return len(stack)

class Solution:
    def maximumStrongPairXor(self, nums: List[int]) -> int:
        max_xor = 0
        n = len(nums)
        for i in range(n):
            for j in range(n):
                x, y = nums[i], nums[j]
                if abs(x - y) <= min(x, y):
                    max_xor = max(max_xor, x ^ y)
        return max_xor

class Solution:
    def maxSpending(self, values: List[List[int]]) -> int:
        # Flatten all items into a single list
        flattened = []
        for row in values:
            flattened.extend(row)

        # Sort in ascending order
        flattened.sort()

        # Calculate total spending
        total = 0
        for i, value in enumerate(flattened):
            total += value * (i + 1)  # Multiply by day index (1-indexed)

        return total

class Solution:
    def maximumPoints(self, edges: List[List[int]], coins: List[int], k: int) -> int:
        from collections import defaultdict
        n = len(coins)
        graph = defaultdict(list)
        for a, b in edges:
            graph[a].append(b)
            graph[b].append(a)

        memo = {}

        def dfs(node, parent, multiplier):
            if (node, parent, multiplier) in memo:
                return memo[(node, parent, multiplier)]

            total_points = 0
            children = []

            for child in graph[node]:
                if child != parent:
                    children.append(child)

            # If no children, we just have to choose one of the two options
            if not children:
                # Option 1: collect normally
                option1 = coins[node] * multiplier - k
                # Option 2: halve coins for subtree (but since no children, it's same as option1)
                option2 = (coins[node] * multiplier) // 2
                total_points = max(option1, option2)
            else:
                # Option 1: collect normally
                option1 = coins[node] * multiplier - k
                # Add points from children with same multiplier
                for child in children:
                    option1 += dfs(child, node, multiplier)

                # Option 2: halve coins for subtree
                option2 = (coins[node] * multiplier) // 2
                # For each child, we use multiplier / 2 because coins are halved
                for child in children:
                    option2 += dfs(child, node, multiplier // 2)

                total_points = max(option1, option2)

            memo[(node, parent, multiplier)] = total_points
            return total_points

        return dfs(0, -1, 1)

class Solution:
    def countSubMultisets(self, nums: List[int], l: int, r: int) -> int:
        MOD = 10**9 + 7
        from collections import Counter
        freq = Counter(nums)
        max_sum = sum(nums)

        dp = [0] * (max_sum + 1)
        dp[0] = 1

        for num, count in freq.items():
            # Process backwards to avoid using updated values
            for s in range(max_sum, -1, -1):
                if dp[s] == 0:
                    continue
                # Try taking 1, 2, ..., count occurrences of num
                for take in range(1, count + 1):
                    next_sum = s + num * take
                    if next_sum <= max_sum:
                        dp[next_sum] = (dp[next_sum] + dp[s]) % MOD

        result = 0
        for i in range(l, r + 1):
            result = (result + dp[i]) % MOD
        return result

class Solution:
    def maxSum(self, nums: List[int], k: int) -> int:
        MOD = 10**9 + 7

        # Count total bits at each position
        bit_count = [0] * 32
        for num in nums:
            for i in range(32):
                if num & (1 << i):
                    bit_count[i] += 1

        # Greedily assign bits to k elements
        # We'll build k largest numbers possible
        result = [0] * k

        # Process from highest bit position to lowest
        for i in range(31, -1, -1):
            # For each bit position, assign it to as many of the k elements as possible
            # But we want to maximize sum of squares, so we should assign higher bits to fewer elements
            # We assign this bit to the first min(bit_count[i], k) elements in our result array
            assign_count = min(bit_count[i], k)
            for j in range(assign_count):
                result[j] |= (1 << i)

        # Calculate sum of squares
        total = 0
        for num in result:
            total = (total + num * num) % MOD

        return total

class Solution:
    def maximumSum(self, nums: List[int]) -> int:
        def get_square_free(n):
            result = 1
            d = 2
            while d * d <= n:
                count = 0
                while n % (d * d) == 0:
                    n //= (d * d)
                if n % d == 0:
                    n //= d
                d += 1
            return n

        groups = {}
        for num in nums:
            sf = get_square_free(num)
            if sf not in groups:
                groups[sf] = 0
            groups[sf] += num

        return max(groups.values())

class Solution:
    def numberOfBeautifulIntegers(self, low: int, high: int, k: int) -> int:
        def count_up_to(num):
            s = str(num)
            n = len(s)
            from functools import lru_cache

            @lru_cache(maxsize=None)
            def dp(pos, remainder, diff, tight, started):
                if pos == n:
                    # Only count if we've started (non-zero digit placed) and divisible by k and equal even/odd digits
                    return 1 if remainder == 0 and diff == 0 and started else 0

                limit = int(s[pos]) if tight else 9
                res = 0
                for digit in range(0, limit + 1):
                    new_tight = tight and (digit == limit)
                    new_remainder = (remainder * 10 + digit) % k
                    new_started = started or (digit > 0)
                    if not started and digit == 0:
                        # Still leading zeros, don't update diff
                        new_diff = diff
                    else:
                        # Update diff based on digit parity
                        new_diff = diff + (1 if digit % 2 == 0 else -1)

                    res += dp(pos + 1, new_remainder, new_diff, new_tight, new_started)

                return res

            return dp(0, 0, 0, True, False)

        return count_up_to(high) - count_up_to(low - 1)

class Solution:
    def maxIncreasingGroups(self, usageLimits: List[int]) -> int:
        usageLimits.sort(reverse=True)
        totalgroup = 0
        ans = 0
        for limit in usageLimits:
            totalgroup += limit
            if totalgroup >= (ans + 1) * (ans + 2) // 2:
                ans += 1
        return ans

from collections import defaultdict, Counter

class Solution:
    def countPalindromePaths(self, parent: List[int], s: str) -> int:
        lookup = defaultdict(list)
        for i, p in enumerate(parent):
            if i > 0:
                lookup[p].append((i, ord(s[i]) - ord('a')))

        counter = Counter()
        total = 0

        def go(node, mask):
            nonlocal total
            total += counter[mask]
            for i in range(26):
                total += counter[mask ^ (1 << i)]
            counter[mask] += 1
            for nxt, c in lookup[node]:
                go(nxt, mask ^ (1 << c))

        go(0, 0)
        return total

class Solution:
    def sumImbalanceNumbers(self, nums: List[int]) -> int:
        n = len(nums)
        total = 0

        for i in range(n):
            for j in range(i, n):
                subarray = nums[i:j+1]
                sorted_sub = sorted(subarray)
                imbalance = 0

                for k in range(len(sorted_sub) - 1):
                    if sorted_sub[k+1] - sorted_sub[k] > 1:
                        imbalance += 1

                total += imbalance

        return total
